def transform(grid):
    """Recolor every complete monochromatic row or column to 2."""
    h, w = len(grid), len(grid[0])
    marked = set()
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row):
            marked.update((r, c) for c in range(w))
    for c in range(w):
        value = grid[0][c]
        if all(grid[r][c] == value for r in range(h)):
            marked.update((r, c) for r in range(h))
    return [[2 if (r, c) in marked else grid[r][c] for c in range(w)] for r in range(h)]
